    "heading": "Hướng dẫn thực hiện",
    "items": [
     {
      "type": "howto",
      "title": "Cài đặt Nginx và lưu trữ nhiều website trên một máy chủ",
      "steps": [
       {
        "text": "Cài Nginx",
        "command": "sudo apt install nginx -y"
       },
       {
        "text": "Tạo thư mục dữ liệu cho site mới",
        "command": "sudo mkdir -p /var/www/site1/html"
       },
       {
        "text": "Tạo file cấu hình server block cho site mới",
        "command": "sudo nano /etc/nginx/sites-available/site1"
       },
       {
        "text": "Nội dung tối thiểu của server block",
        "command": "server {\n  listen 80;\n  server_name site1.local;\n  root /var/www/site1/html;\n  index index.html;\n}"
       },
       {
        "text": "Bật site bằng symlink sang sites-enabled",
        "command": "sudo ln -s /etc/nginx/sites-available/site1 /etc/nginx/sites-enabled/"
       },
       {
        "text": "Kiểm tra cú pháp cấu hình trước khi áp dụng",
        "command": "sudo nginx -t"
       },
       {
        "text": "Nạp lại cấu hình không làm rớt kết nối đang mở",
        "command": "sudo systemctl reload nginx"
       }
      ]
     },
     {
      "type": "howto",
      "title": "Cấp chứng chỉ HTTPS miễn phí bằng Let's Encrypt (certbot)",
      "steps": [
       {
        "text": "Cài certbot và plugin cho Nginx",
        "command": "sudo apt install certbot python3-certbot-nginx -y"
       },
       {
        "text": "Yêu cầu và tự động gắn chứng chỉ vào site đã cấu hình trong Nginx",
        "command": "sudo certbot --nginx -d site1.example.com"
       },
       {
        "text": "Kiểm tra site đã chuyển sang HTTPS",
        "command": "curl -I https://site1.example.com"
       },
       {
        "text": "Kiểm thử việc gia hạn tự động (không thực sự gia hạn)",
        "command": "sudo certbot renew --dry-run"
       }
      ]
     }
    ]
